/bin/bash -lc "Rscript - <<'RS'
paths <- c(\"/workspace/inputs/res_1vs97.rds\", \"/workspace/inputs/res_1vs98.rds\", \"/workspace/inputs/res_1vs99.rds\")
res <- lapply(paths, function(p) {
  x <- readRDS(p); ld <- attr(x, \"listData\")
  data.frame(gene=attr(x, \"rownames\"), lfc=ld"'$log2FoldChange, padj=ld$padj, stringsAsFactors=FALSE)
})
names(res) <- sub("res_", "", sub("'"\\\\.rds"'$", "", basename(paths)))
links <- read.delim("https://rest.kegg.jp/link/pathway/pau", header=FALSE, sep="'"\\t\", quote=\"\", stringsAsFactors=FALSE)
colnames(links) <- c(\"gene\", \"pathway\")
links"'$gene <- sub("''^pau:", "", links$gene); links$pathway <- sub("''^path:", "", links$pathway)
pathgenes <- lapply(split(links$gene, links$pathway), unique)
allres <- unique(unlist(lapply(res, `[[`, "gene")))
uni <- intersect(allres, unique(links$gene))

o <- function(fg, universe=uni, minGS=1, maxGS=Inf, family="hits") {
  gs <- lapply(pathgenes, intersect, y=universe)
  sz <- lengths(gs); keep <- sz >= minGS & sz <= maxGS
  k <- vapply(gs, function(g) length(intersect(g, fg)), integer(1))
  tested <- keep & k > 0
  N <- length(universe); n <- length(intersect(fg, universe)); M <- sz
  p <- rep(NA_real_, length(gs)); p[tested] <- phyper(k[tested]-1, M[tested], N-M[tested], n, lower.tail=FALSE)
  padj <- rep(NA_real_, length(gs));
  if (family == "hits") padj[tested] <- p.adjust(p[tested], "BH") else if (family == "all") padj[keep] <- p.adjust(p[keep], "BH")
  data.frame(pathway=names(gs), size=sz, hit=k, p=p, padj=padj, tested=tested, stringsAsFactors=FALSE)
}
for (minGS in c(1, 5, 10)) for (maxGS in c(Inf,500)) {
  cat("'"\\n=== min\", minGS, \"max\", maxGS, \"===\\n\")
  sets <- list()
  for (sgn in c(\"pos\", \"neg\")) {
    sig <- list()
    for (nm in names(res)) {
      d <- res[[nm]]
      fg <- if (sgn==\"pos\") d"'$gene[d$lfc > 1.5] else d$gene[d$lfc < -1.5]
      z <- o(fg, minGS=minGS, maxGS=maxGS, family="hits")
      sig[[nm]] <- z$pathway[!is.na(z$padj) & z$padj < .05]
      cat(sgn, nm, "fg", length(intersect(fg,uni)), "tested", sum(z$tested), "sig", length(sig[[nm]]), "rawsig", sum(z$p < .05,na.rm=TRUE), "'"\\n\")
      if (length(sig[[nm]])>0) cat(\"  \", paste(sig[[nm]], collapse=\",\"), \"\\n\")
    }
    inter <- Reduce(intersect, sig); sets[[sgn]] <- inter
    cat(\"INTER\", sgn, length(inter), paste(inter, collapse=\",\"), \"\\n\")
  }
  cat(\"TOTAL\", length(unique(unlist(sets))), \"SUM\", sum(lengths(sets)), \"\\n\")
}
RS"

/bin/bash -lc "Rscript - <<'RS'
paths <- c(\"/workspace/inputs/res_1vs97.rds\", \"/workspace/inputs/res_1vs98.rds\", \"/workspace/inputs/res_1vs99.rds\")
res <- lapply(paths, function(p) { x <- readRDS(p); ld <- attr(x,\"listData\"); data.frame(gene=attr(x,\"rownames\"),lfc=ld"'$log2FoldChange,padj=ld$padj) })
names(res) <- c("97","98","99")
links <- read.delim("https://rest.kegg.jp/link/pathway/pau",header=FALSE,sep="'"\\t\",quote=\"\",stringsAsFactors=FALSE)
links"'$V1 <- sub("''^pau:","",links$V1); links$V2 <- sub("''^path:","",links$V2)
gs0 <- lapply(split(links$V1,links$V2),unique)
run <- function(fg, uni, minGS=1,maxGS=Inf, family=c("hits","all","all137"), alpha=.05) {
  family <- match.arg(family); gs <- lapply(gs0,intersect,y=uni); sz <- lengths(gs); k <- vapply(gs,function(z)length(intersect(z,fg)),integer(1)); keep <- sz>=minGS & sz<=maxGS; test <- keep & k>0; N <- length(uni); n <- length(intersect(fg,uni)); p <- rep(NA_real_,length(gs)); p[test] <- phyper(k[test]-1,sz[test],N-sz[test],n,lower.tail=FALSE); pa <- rep(NA_real_,length(gs)); idx <- if(family=="hits") test else if(family=="all") keep else rep(TRUE,length(gs)); pa[idx] <- p.adjust(p[idx],"BH"); list(sig=names(gs)[!is.na(pa)&pa<alpha],raw=names(gs)[!is.na(p)&p<alpha],p=p,pa=pa,k=k,sz=sz,test=test)
}
for (un in c("res","kegg")) {
  uni <- if(un=="res") unique(unlist(lapply(res,`[[`,"gene"))) else unique(links$V1)
  cat("'"\\nUNIVERSE\",un,length(uni),\"\\n\")
  for (fam in c(\"hits\",\"all\",\"all137\")) for (thr in c(\"padj\",\"raw\")) {
    ss <- lapply(res,function(d) { z <- if(thr==\"padj\") d"'$padj<.05 & abs(d$lfc)>1.5 else abs(d$lfc)>1.5; lapply(list(pos=d$gene[z & d$lfc>0],neg=d$gene[z & d$lfc<0]), function(fg) run(fg,uni,family=fam)) })
    for (sgn in c("pos","neg")) { ints <- Reduce(intersect,lapply(ss,`[[`,sgn)); cat(fam,thr,sgn,"inter",length(ints),paste(ints,collapse=","),"sum sig",sum(sapply(ss, function(x)length(x[[sgn]]$sig))),"'"\\n\") }
  }
}
RS"

/bin/bash -lc "Rscript - <<'RS'
paths <- c(\"/workspace/inputs/res_1vs97.rds\", \"/workspace/inputs/res_1vs98.rds\", \"/workspace/inputs/res_1vs99.rds\")
res <- lapply(paths, function(p) { x <- readRDS(p); ld <- attr(x,\"listData\"); data.frame(gene=attr(x,\"rownames\"),lfc=ld"'$log2FoldChange,padj=ld$padj) })
names(res) <- c("97","98","99")
links <- read.delim("https://rest.kegg.jp/link/pathway/pau",header=FALSE,sep="'"\\t\",quote=\"\",stringsAsFactors=FALSE)
links"'$V1 <- sub("''^pau:","",links$V1); links$V2 <- sub("''^path:","",links$V2)
gs0 <- lapply(split(links$V1,links$V2),unique)
run <- function(fg, uni, minGS=1,maxGS=Inf, family="hits", cutoff="padj") {
  gs <- lapply(gs0,intersect,y=uni); sz <- lengths(gs); k <- vapply(gs,function(z)length(intersect(z,fg)),integer(1)); keep <- sz>=minGS & sz<=maxGS; test <- keep & k>0; N <- length(uni); n <- length(intersect(fg,uni)); p <- rep(NA_real_,length(gs)); p[test] <- phyper(k[test]-1,sz[test],N-sz[test],n,lower.tail=FALSE); pa <- rep(NA_real_,length(gs)); idx <- if(family=="hits") test else keep; pa[idx] <- p.adjust(p[idx],"BH"); sig <- if(cutoff=="padj") pa<.05 else p<.05; names(gs)[which(!is.na(sig)&sig)]
}
report <- function(uniName, uni, family, minGS, maxGS, cutoff) {
  out <- list(); cat("U",uniName,"N",length(uni),"family",family,"min",minGS,"max",maxGS,"cut",cutoff,"'"\\n\")
  for (sgn in c(\"pos\",\"neg\")) { x <- lapply(res,function(d) { z <- d"'$lfc > 1.5; if(sgn=="neg") z <- d$lfc < -1.5; if(cutoff=="padj") z <- z & d$padj<.05; run(d$gene[z],uni,minGS,maxGS,family,cutoff) }); inter <- Reduce(intersect,x); cat(sgn,"sizes",paste(lengths(x),collapse=","),"inter",length(inter),paste(inter,collapse=","),"'"\\n\"); out[[sgn]] <- inter }
  cat(\"total\",length(unique(unlist(out))),\"sum\",sum(lengths(out)),\"\\n\")
}
for (uniName in c(\"res\",\"kegg\")) { uni <- if(uniName==\"res\") unique(unlist(lapply(res,"'`[[`,"gene"))) else unique(links$V1); for (family in c("hits","all")) for (cutoff in c("padj","raw")) report(uniName,uni,family,1,Inf,cutoff) }
RS'

